+export function findRoomServing(
+  logPath: string,
+  lists: { live: RoomRegistryEntry[]; unconfirmed: RoomRegistryEntry[] },
+): RoomRegistryEntry | undefined {
+  return [...lists.live, ...lists.unconfirmed].find((room) => room.logPath === logPath);
